pm.test("Tipo de Usário criado com sucesso", () => {
    pm.response.to.have.status(201)
})

const resp = pm.response.json()
pm.collectionVariables.set("CREATED_SUBROLE_ID", resp.id);

pm.test("Erro ao criar tipo de usuário que já existe", () => {
    pm.response.to.have.status(409)
})

pm.test("Erro de permissão ao criar tipo de usuário", () => {
    pm.response.to.have.status(403)
})

pm.test("Atualizado com sucesso", () => {
    pm.response.to.have.status(200)
})

const resp = pm.response.json()
pm.collectionVariables.set("CREATED_SUBROLE_ID", resp.id)

pm.test("Erro de permissão ao deletar tipo de usuário", () => {
    pm.response.to.have.status(403)
})

pm.test("Tipo de usuário não econtrado", () => {
    pm.response.to.have.status(404)
})

pm.test("Subrole atribuído com sucesso", () => {
    pm.response.to.have.status(200)
})
pm.test("Vínculo corresponde à atribuição solicitada", () => {
    const resp = pm.response.json()
    pm.expect(resp.id).to.be.a("string").and.not.empty;
    pm.expect(resp.userId).to.eql(pm.variables.get("ASSIGN_USER_ID"));
    pm.expect(resp.subRoleId).to.eql(pm.variables.get("ASSIGN_SUBROLE_ID"));
    pm.expect(resp.restaurantId).to.eql(pm.variables.get("ASSIGN_RESTAURANT_ID"))
})

const resp = pm.response.json()
pm.collectionVariables.set("ASSIGNED_MEMBERSHIP_ID", resp.id);

pm.test("Resposta retornou 200", () => {
    pm.response.to.have.status(200)
})
pm.test("Vínculo corresponde à atribuição solicitada", () => {
    const resp = pm.response.json()
    pm.expect(resp.id).to.be.a("string").and.not.empty;
    pm.expect(resp.userId).to.eql(pm.variables.get("ASSIGN_USER_ID"));
    pm.expect(resp.subRoleId).to.eql(pm.variables.get("ASSIGN_SUBROLE_ID"));
    pm.expect(resp.restaurantId).to.eql(pm.variables.get("ASSIGN_RESTAURANT_ID"))
})
pm.test("Preservou o ID do vínculo", () => {
    pm.expect(pm.response.json().id).to.eql(pm.variables.get("ASSIGNED_MEMBERSHIP_ID"))
})

pm.test("mainOwner atribuiu subrole no próprio restaurante", () => {
    pm.response.to.have.status(200)
})

const resp = pm.response.json()
pm.collectionVariables.set("ASSIGNED_MEMBERSHIP_ID", resp.id);

pm.test("Assign Subrole - Erro - Proprietário de outro restaurante", () => {
    pm.response.to.have.status(403)
})

pm.test("Assign Subrole - Erro - mainOwner atribui ADMIN", () => {
    pm.response.to.have.status(403)
})

pm.test("Assign Subrole - ADMIN atribui mainOwner", () => {
    pm.response.to.have.status(200)
})

pm.test("Assign Subrole - ADMIN substitui mainOwner", () => {
    pm.response.to.have.status(200)
})

pm.test("Item do cardápio criado com sucesso", () => {
    pm.response.to.have.status(200)
})

const resp = pm.response.json()
pm.collectionVariables.set("CREATED_MENUITEM_ID", resp.id);

pm.test("Resposta retornou 200", () => {
    pm.response.to.have.status(200)
})
pm.test("Retornou o item solicitado", () => {
    pm.expect(pm.response.json().id).to.eql(pm.variables.get("CREATED_MENUITEM_ID"))
})

pm.test("Resposta retornou 204", () => {
    pm.response.to.have.status(204)
})
pm.test("Resposta sem corpo", () => {
    pm.expect(pm.response.text()).to.eql("")
})

pm.test("Restaurante criado com sucesso", () => {
    pm.response.to.have.status(200)
})

const resp = pm.response.json()
pm.collectionVariables.set("CREATED_RESTAURANT_ID", resp.id);

pm.test("Resposta retornou 200", () => {
    pm.response.to.have.status(200)
})
pm.test("Retornou o restaurante solicitado e suas coleções", () => {
    const resp = pm.response.json()
    pm.expect(resp.id).to.eql(pm.variables.get("CREATED_RESTAURANT_ID"));
    pm.expect(resp.membershipIds).to.be.an("array");
    pm.expect(resp.menuItemsIdList).to.be.an("array")
})

pm.test("Resposta retornou 200", () => {
    pm.response.to.have.status(200)
})
pm.test("Nome atualizado", () => {
    pm.expect(pm.response.json().name).to.eql("Restaurante Postman atualizado")
})

